# hello.nomad
job "hello" {
  datacenters = ["dc1"]
  type        = "service"

  group "web" {
    count = 1

    task "server" {
      driver = "docker"

      config {
        image   = "nginx:alpine"
        ports   = ["http"]
      }

      resources {
        cpu    = 100
        memory = 128
      }
    }
  }
}

# Exécution : nomad job run hello.nomad
